window.QUIZ_BANK['playwright'] = (window.QUIZ_BANK['playwright']||[]).concat([
{id:4601,topic:'playwright',difficulty:'beginner',question:'Which Playwright method is used to locate elements inside an iframe?',options:['page.frame()','page.frameLocator()','page.querySelector()','page.contentFrame()'],answer:1,explanation:'page.frameLocator(selector) returns a FrameLocator object that allows you to chain further locator calls scoped to the matched iframe, enabling auto-waiting and web-first assertion patterns inside frames.'},
{id:4602,topic:'playwright',difficulty:'intermediate',question:'Given a FrameLocator stored as `const frame = page.frameLocator("#my-iframe")`, how do you click a button with text "Submit" inside it?',options:['frame.click("Submit")','frame.locator("text=Submit").click()','page.click("#my-iframe >> text=Submit")','frame.getByText("Submit").click()'],answer:3,explanation:'Both frame.locator("text=Submit").click() and frame.getByText("Submit").click() are correct; however, getByText is the idiomatic modern API. The FrameLocator chains standard locator methods so all auto-waiting and retry mechanisms apply seamlessly.'},
{id:4603,topic:'playwright',difficulty:'intermediate',question:'What does page.waitForEvent("popup") return?',options:['A BrowserContext','A Page object for the newly opened tab or window','A Frame object','A Locator for the popup element'],answer:1,explanation:'page.waitForEvent("popup") returns a Promise that resolves to the new Page object representing the popup or new tab. You typically race it with the action that triggers the popup so the handler is registered before the popup opens.'},
{id:4604,topic:'playwright',difficulty:'beginner',question:'What is the correct pattern to capture a popup triggered by a button click?',options:['const popup = await page.waitForEvent("popup"); await page.click("#open");','const [popup] = await Promise.all([page.waitForEvent("popup"), page.click("#open")]);','await page.click("#open"); const popup = page.popup();','page.on("popup", fn); await page.click("#open");'],answer:1,explanation:'The recommended pattern is Promise.all so that the waitForEvent listener is registered before the action fires, preventing race conditions where the popup opens and closes before the listener is attached.'},
{id:4605,topic:'playwright',difficulty:'intermediate',question:'How can you open a brand-new tab manually in Playwright without triggering a link click?',options:['browser.newPage()','context.newPage()','page.newTab()','browserContext.openPage()'],answer:1,explanation:'context.newPage() creates a fresh Page inside the existing BrowserContext, inheriting cookies, storage state, and network settings. browser.newPage() creates a page in an isolated default context instead.'},
{id:4606,topic:'playwright',difficulty:'intermediate',question:'In a multi-tab test, after storing `const page2 = await context.newPage()` you navigate page2 to a URL. Which assertion verifies that page2 has loaded the correct URL?',options:['expect(page2.url()).toBe(url)','await expect(page2).toHaveURL(url)','assert page2.currentUrl === url','page2.waitForURL(url)'],answer:1,explanation:'await expect(page2).toHaveURL(url) is the web-first assertion that retries until the page URL matches, handling redirects and slow navigation gracefully. Direct url() comparison is a point-in-time check without retry.'},
{id:4607,topic:'playwright',difficulty:'intermediate',question:'Which Playwright method performs a drag-and-drop from one element to another in a single call?',options:['page.drag(source, target)','locator.dragTo(targetLocator)','page.mouse.drag(source, target)','locator.drop(targetLocator)'],answer:1,explanation:'locator.dragTo(targetLocator) dispatches the necessary pointerdown, pointermove, and pointerup events to simulate a complete drag-and-drop interaction between two elements, handling coordinates automatically.'},
{id:4608,topic:'playwright',difficulty:'intermediate',question:'How do you perform a drag and drop using raw mouse events when dragTo() is insufficient?',options:['Use page.mouse.move(), page.mouse.down(), page.mouse.move() to target, page.mouse.up()','Use page.dragAndDrop(source, target, {force:true})','Use locator.hover() then locator.click({button:"right"})','Use keyboard.press("ControlOrMeta+D")'],answer:0,explanation:'The manual mouse-based approach calls page.mouse.move() to the source, page.mouse.down(), then page.mouse.move() to the destination (optionally in small steps), and finally page.mouse.up(). This simulates the exact pointer event sequence for complex drag libraries.'},
{id:4609,topic:'playwright',difficulty:'beginner',question:'Which Playwright method sets files on a file input element?',options:['locator.uploadFile()','locator.setInputFiles()','page.attachFile()','page.uploadFile()'],answer:1,explanation:'locator.setInputFiles(pathOrPaths) accepts a single path string, an array of paths, or a FilePayload object. It programmatically fills the file input without opening a native OS dialog, making it deterministic and CI-friendly.'},
{id:4610,topic:'playwright',difficulty:'intermediate',question:'How do you upload multiple files at once using Playwright?',options:['locator.setInputFiles(["file1.png","file2.pdf"])','locator.setInputFiles("file1.png","file2.pdf")','locator.click(); page.keyboard.type("file1.png,file2.pdf")','locator.addFile(["file1.png","file2.pdf"])'],answer:0,explanation:'Passing an array of paths to setInputFiles() selects multiple files simultaneously on the input element, matching what a user would do by ctrl-clicking multiple files in a native file picker dialog.'},
{id:4611,topic:'playwright',difficulty:'intermediate',question:'When a web app opens a custom file-chooser UI (not a native input), which Playwright pattern should you use?',options:['page.waitForEvent("filechooser") then call fileChooser.setFiles()','Directly call page.setInputFiles()','page.on("dialog") then dialog.accept(path)','page.keyboard.type(filePath) after focusing the input'],answer:0,explanation:'page.waitForEvent("filechooser") returns a FileChooser object when the page triggers a file-chooser. You then call fileChooser.setFiles(paths) to fulfil the chooser, even when the app uses a custom file-upload button wired to a hidden input.'},
{id:4612,topic:'playwright',difficulty:'beginner',question:'Which method changes the viewport size of a Playwright page at runtime?',options:['page.setViewport({width,height})','page.setViewportSize({width,height})','browser.setViewport({width,height})','page.resize({width,height})'],answer:1,explanation:'page.setViewportSize({width, height}) updates the viewport dimensions for the current page. Unlike Puppeteer which uses setViewport, Playwright uses setViewportSize. The change takes effect immediately for subsequent interactions.'},
{id:4613,topic:'playwright',difficulty:'intermediate',question:'How do you emulate a specific mobile device (e.g., iPhone 13) in a Playwright test?',options:['await browser.newContext({device:"iPhone 13"})','const iPhone = playwright.devices["iPhone 13"]; await browser.newContext({...iPhone})','await page.emulate("iPhone 13")','context.setDevice("iPhone 13")'],answer:1,explanation:'playwright.devices is a dictionary of device descriptors containing viewport, userAgent, deviceScaleFactor, isMobile, and hasTouch. Spreading the descriptor into newContext() applies all emulation settings at once.'},
{id:4614,topic:'playwright',difficulty:'beginner',question:'Where is the playwright.devices dictionary exported from in Node.js?',options:['require("playwright").devices','require("playwright/test").devices','require("@playwright/test").chromium.devices','import devices from "playwright-core"'],answer:0,explanation:'The devices dictionary is available from the top-level "playwright" or "playwright-core" packages (e.g., const { devices } = require("playwright")). In test files you typically import it from @playwright/test via the test fixture or directly from playwright.'},
{id:4615,topic:'playwright',difficulty:'intermediate',question:'How do you override geolocation in a Playwright BrowserContext?',options:['page.setGeolocation({latitude, longitude})','context.setGeolocation({latitude, longitude}) after granting "geolocation" permission','browser.newContext({geolocation:{latitude,longitude}})','Both B and C are correct'],answer:3,explanation:'You can pass geolocation in the newContext() options, or update it later with context.setGeolocation(). In both cases you must also grant the "geolocation" permission via context.grantPermissions(["geolocation"]) so the browser does not block the API.'},
{id:4616,topic:'playwright',difficulty:'intermediate',question:'Which option in BrowserContext settings overrides the timezone seen by the page?',options:['locale','timezoneId','timezone','utcOffset'],answer:1,explanation:'Passing timezoneId: "America/New_York" (or any IANA timezone string) to browser.newContext() makes Date objects and Intl APIs in the page reflect that timezone, enabling reliable timezone-sensitive test scenarios.'},
{id:4617,topic:'playwright',difficulty:'beginner',question:'Which Playwright API grants permissions like notifications or camera to a context?',options:['context.grantPermissions(["notifications"])','page.allow("notifications")','browser.setPermissions(["camera"])','context.allowPermissions(["camera","microphone"])'],answer:0,explanation:'context.grantPermissions(permissions, {origin}) grants one or more permission strings for the given context. Supported values include "geolocation", "notifications", "camera", "microphone", "clipboard-read", and others defined by the Permissions API.'},
{id:4618,topic:'playwright',difficulty:'intermediate',question:'How do you emulate a dark color scheme preference in Playwright?',options:['page.emulateMedia({colorScheme:"dark"})','context.newPage({colorScheme:"dark"})','browser.newContext({colorScheme:"dark"})','Both A and C are correct, A at page level, C at context level'],answer:3,explanation:'colorScheme can be set at context creation via browser.newContext({colorScheme:"dark"}) or changed per-page at runtime with page.emulateMedia({colorScheme:"dark"}). Both affect the CSS prefers-color-scheme media query inside the page.'},
{id:4619,topic:'playwright',difficulty:'intermediate',question:'Which Playwright option emulates the CSS "prefers-reduced-motion: reduce" media feature?',options:['context option: reducedMotion:"reduce"','page.emulateMedia({reducedMotion:"reduce"})','browser.newContext({reducedMotion:"reduce"})','Both B and C are valid'],answer:3,explanation:'reducedMotion:"reduce" is accepted at context creation (browser.newContext) and can be applied or changed per-page with page.emulateMedia(). It sets the prefers-reduced-motion CSS media feature, useful for testing accessible animation-disabled experiences.'},
{id:4620,topic:'playwright',difficulty:'intermediate',question:'How do you simulate the user being offline in a Playwright test?',options:['page.setOffline(true)','context.setOffline(true)','browser.newContext({offline:true})','Both B and C work'],answer:3,explanation:'context.setOffline(true) toggles offline mode at runtime for all pages in a context. You can also start offline from the start by passing offline:true to browser.newContext(). This triggers network failures as if the user had no internet connection.'},
{id:4621,topic:'playwright',difficulty:'intermediate',question:'What does storageState save in Playwright, and why is it used?',options:['Browser binary version for reproducible runs','Cookies, localStorage, and sessionStorage for auth state reuse','Test results and screenshots for reporting','Browser context configuration settings'],answer:1,explanation:'storageState captures cookies and Web Storage (localStorage/sessionStorage) from a logged-in session. Saving it once in a global setup and loading it in each test skips repetitive login flows, dramatically speeding up test suites.'},
{id:4622,topic:'playwright',difficulty:'intermediate',question:'How do you save the current authentication state to a file?',options:['await page.saveState("auth.json")','await context.storageState({path:"auth.json"})','await browser.saveAuth("auth.json")','await page.cookies("auth.json")'],answer:1,explanation:'context.storageState({path: "auth.json"}) serializes all cookies and storage entries to a JSON file. This file is later referenced in playwright.config.ts under use.storageState or passed directly to browser.newContext({storageState:"auth.json"}).'},
{id:4623,topic:'playwright',difficulty:'intermediate',question:'Where in playwright.config.ts do you specify a global setup file that runs once before all tests?',options:['setup: "./global-setup.ts"','globalSetup: "./global-setup.ts"','beforeAll: "./global-setup.ts"','testSetup: "./global-setup.ts"'],answer:1,explanation:'The globalSetup property in playwright.config.ts points to a module that exports a default async function. Playwright runs it once before the entire test suite, making it ideal for seeding databases or saving authentication state.'},
{id:4624,topic:'playwright',difficulty:'intermediate',question:'How do you specify a global teardown file in playwright.config.ts?',options:['afterAll: "./global-teardown.ts"','globalTeardown: "./global-teardown.ts"','teardown: "./global-teardown.ts"','cleanup: "./global-teardown.ts"'],answer:1,explanation:'globalTeardown mirrors globalSetup. It accepts a path to a module exporting a default async function that Playwright runs once after all tests complete, suitable for cleaning databases or deleting temporary resources.'},
{id:4625,topic:'playwright',difficulty:'beginner',question:'What does setting `baseURL: "https://example.com"` in playwright.config.ts allow you to do?',options:['Automatically proxy all requests through example.com','Use relative paths like "/" or "/login" in page.goto() calls','Set the default page title expectation','Define the origin for CORS testing'],answer:1,explanation:'When baseURL is configured, page.goto("/login") resolves to "https://example.com/login". This eliminates duplication of the host in every test and makes it easy to switch environments by updating a single config value.'},
{id:4626,topic:'playwright',difficulty:'intermediate',question:'What is the correct timeout hierarchy from broadest to most specific in Playwright?',options:['Action → Test → Global','Global playwright.config timeout → Test timeout → Action/assertion timeout','Test → Action → Global','Navigation timeout → Test timeout → Global timeout'],answer:1,explanation:'Playwright applies timeouts at multiple levels: the top-level timeout in config sets the default test timeout; testTimeout per test overrides it; individual action timeouts (locator.click({timeout})) override for a single action; expect.configure({timeout}) overrides assertion retries.'},
{id:4627,topic:'playwright',difficulty:'intermediate',question:'Which timeout config key controls the maximum time a single test can run?',options:['actionTimeout','testTimeout','timeout','globalTimeout'],answer:2,explanation:'In playwright.config.ts, the timeout property (under the root or inside use) sets the default per-test timeout in milliseconds. testTimeout is not a standard config key — the correct key is simply "timeout" at the config root level.'},
{id:4628,topic:'playwright',difficulty:'intermediate',question:'How do you set a default timeout for all assertions (expect calls) in playwright.config.ts?',options:['use: { assertionTimeout: 5000 }','expect: { timeout: 5000 }','use: { expectTimeout: 5000 }','assertions: { timeout: 5000 }'],answer:1,explanation:'The expect object in playwright.config.ts accepts a timeout key that sets the default retry interval for all web-first assertions globally. This is separate from the action timeout and can also be overridden per-assertion with expect.configure().'},
{id:4629,topic:'playwright',difficulty:'beginner',question:'What environment variable enables Playwright Inspector for step-by-step debugging?',options:['DEBUG=pw:api','PLAYWRIGHT_DEBUG=1','PWDEBUG=1','PW_INSPECT=1'],answer:2,explanation:'Setting PWDEBUG=1 before running tests launches Playwright Inspector, pauses execution at the first action, and opens a GUI to step through actions, inspect the DOM, and view the selector under the cursor in real time.'},
{id:4630,topic:'playwright',difficulty:'beginner',question:'Which CLI flags run Playwright tests in a visible browser with slowed-down actions for manual observation?',options:['--debug --pause','--headed --slowMo','--headless=false --delay','--visible --slow'],answer:1,explanation:'--headed forces a visible browser window, and --slowMo=N (passed in code as slowMo: N in launchOptions) adds N milliseconds between actions. Together they let you watch the test execution frame by frame to spot issues.'},
{id:4631,topic:'playwright',difficulty:'beginner',question:'Which Playwright API call pauses test execution and opens the Inspector mid-test?',options:['test.pause()','debugger','await page.pause()','await playwright.inspect()'],answer:2,explanation:'await page.pause() suspends the test at that point and opens Playwright Inspector, allowing interactive DOM exploration, locator evaluation, and resuming execution. It requires PWDEBUG=1 or --headed mode to be useful.'},
{id:4632,topic:'playwright',difficulty:'beginner',question:'What does `npx playwright codegen https://example.com` do?',options:['Runs all tests against example.com','Opens a browser, records user interactions, and generates Playwright test code','Downloads example.com for offline testing','Generates a performance profile of example.com'],answer:1,explanation:'Playwright Codegen opens a Chromium browser and, as you interact with the page, generates corresponding Playwright API calls in real time. The generated code can be copied to a test file as a starting point, saving manual writing effort.'},
{id:4633,topic:'playwright',difficulty:'intermediate',question:'Which codegen CLI option saves the generated script directly to a file?',options:['npx playwright codegen --out script.ts URL','npx playwright codegen --save script.ts URL','npx playwright codegen -o script.ts URL','npx playwright codegen --output=script.ts URL'],answer:2,explanation:'The -o (or --output) flag tells codegen to write the generated test code to the specified file path. Without it, code appears only in the Codegen Inspector window and must be copied manually.'},
{id:4634,topic:'playwright',difficulty:'intermediate',question:'What is a key advantage of using TypeScript with Playwright compared to plain JavaScript?',options:['TypeScript tests run faster because V8 optimises type annotations','Type-checking catches API misuse (wrong argument types, missing await) at compile time','TypeScript generates smaller test bundles','TypeScript supports more browsers than JavaScript'],answer:1,explanation:'TypeScript provides static types for all Playwright APIs. Mistakes like passing a string where a Locator is expected, or forgetting to await a Promise, become compile-time errors rather than silent runtime failures discovered during CI runs.'},
{id:4635,topic:'playwright',difficulty:'beginner',question:'Is TypeScript required to use Playwright?',options:['Yes, Playwright only supports TypeScript','No, Playwright works equally well with plain JavaScript','Only for the test runner; core APIs require TypeScript','Only when using fixtures'],answer:1,explanation:'Playwright is a pure JavaScript library at runtime. TypeScript is optional and recommended for larger projects but any .js test file works with the @playwright/test runner without any TypeScript configuration.'},
{id:4636,topic:'playwright',difficulty:'beginner',question:'Which Python package provides the synchronous Playwright API?',options:['playwright.async_api','playwright.sync_api','playwright.browser','playwright.chromium'],answer:1,explanation:'playwright.sync_api exposes a synchronous interface where all Playwright calls block until completion, making it feel like ordinary sequential Python code. playwright.async_api uses Python asyncio coroutines for asynchronous usage.'},
{id:4637,topic:'playwright',difficulty:'intermediate',question:'What is the correct way to launch a browser in Python sync Playwright?',options:['from playwright.sync_api import sync_playwright; with sync_playwright() as p: browser = p.chromium.launch()','import playwright; playwright.chromium.launch()','from playwright import Playwright; p = Playwright(); p.launch()','playwright.run(lambda p: p.chromium.launch())'],answer:0,explanation:'sync_playwright() returns a context manager. Inside the with block, p is a Playwright instance exposing browser type launchers (p.chromium, p.firefox, p.webkit). Using the context manager ensures proper cleanup when the block exits.'},
{id:4638,topic:'playwright',difficulty:'intermediate',question:'Which Maven/Gradle dependency provides the Playwright Java API?',options:['com.microsoft.playwright:playwright','org.playwright:java-sdk','io.playwright:playwright-java','com.google.playwright:playwright'],answer:0,explanation:'The official Java binding is published under the Maven coordinate com.microsoft.playwright:playwright. It mirrors the Node.js API closely, with synchronous method calls, and supports Chromium, Firefox, and WebKit.'},
{id:4639,topic:'playwright',difficulty:'intermediate',question:'Which NuGet package adds Playwright support to a .NET C# project?',options:['Playwright.NET','Microsoft.Playwright','Selenium.Playwright','Playwright.CSharp'],answer:1,explanation:'Microsoft.Playwright is the official NuGet package. After adding it, you run `playwright install` via the Playwright.CLI tool to download browser binaries. The API mirrors the Node.js library closely using async/await patterns.'},
{id:4640,topic:'playwright',difficulty:'intermediate',question:'Which community library integrates axe-core accessibility checks into Playwright Node.js tests?',options:['playwright-axe','axe-playwright','@axe-core/playwright','playwright-accessibility'],answer:1,explanation:'axe-playwright (npm) wraps axe-core and provides an injectAxe() helper and checkA11y() function. You inject axe into the page and then run checks, receiving structured accessibility violation reports in your test output.'},
{id:4641,topic:'playwright',difficulty:'intermediate',question:'Which Playwright built-in API captures an accessibility tree snapshot without a third-party library?',options:['page.accessibility.snapshot()','page.getAXTree()','page.ariaSnapshot()','locator.accessibility()'],answer:0,explanation:'page.accessibility.snapshot() returns a tree of AXNode objects representing the accessible name, role, and properties of each element. It is useful for assertions on landmark structure and ARIA attributes without requiring axe-core.'},
{id:4642,topic:'playwright',difficulty:'beginner',question:'What load state does `page.waitForLoadState("networkidle")` wait for?',options:['The DOMContentLoaded event fires','All network requests complete and no new requests start for 500 ms','The first paint occurs','The page title is set'],answer:1,explanation:'"networkidle" waits until there are no more than 0 in-flight network requests for at least 500 milliseconds. It is useful for SPAs with background XHR calls but can be slow — prefer waiting for specific elements or responses when possible.'},
{id:4643,topic:'playwright',difficulty:'intermediate',question:'What is the difference between waitForLoadState("load") and waitForLoadState("domcontentloaded")?',options:['"load" waits for the load event (all resources); "domcontentloaded" only waits for HTML parsing to finish','"domcontentloaded" waits for all images; "load" only waits for scripts','"load" is for navigation; "domcontentloaded" is for AJAX calls','They are equivalent aliases'],answer:0,explanation:'"domcontentloaded" fires when the HTML is parsed and the DOM is built, before external resources like images and stylesheets finish. "load" fires after all subresources complete. Use "domcontentloaded" when you do not need images and want faster tests.'},
{id:4644,topic:'playwright',difficulty:'intermediate',question:'Which Playwright API waits for the page URL to match a given string or regex?',options:['page.waitForURL(urlOrRegex)','expect(page).toHaveURL(urlOrRegex)','page.waitForNavigation({url:urlOrRegex})','Both A and B'],answer:3,explanation:'page.waitForURL() is a navigation-focused wait that resolves when the URL matches. expect(page).toHaveURL() is a web-first assertion that retries the check. Both are valid depending on context: use waitForURL when you need to gate subsequent steps, and toHaveURL for assertions.'},
{id:4645,topic:'playwright',difficulty:'beginner',question:'Which assertion checks that a Playwright page has a specific URL?',options:['expect(page.url()).toBe(url)','await expect(page).toHaveURL(url)','page.assertURL(url)','expect(page).url().equals(url)'],answer:1,explanation:'await expect(page).toHaveURL(url) is the web-first form that retries until the URL matches or the timeout expires. It handles redirects and slow navigation, unlike the synchronous page.url() comparison which only checks the current moment.'},
{id:4646,topic:'playwright',difficulty:'beginner',question:'Which assertion verifies the page title in Playwright?',options:['expect(await page.title()).toBe(title)','await expect(page).toHaveTitle(title)','page.assertTitle(title)','expect(page.title).toBe(title)'],answer:1,explanation:'await expect(page).toHaveTitle(title) retries until the document title matches the expected string or regex. It is preferable to await page.title() + toBe() because it handles pages that set the title asynchronously after navigation.'},
{id:4647,topic:'playwright',difficulty:'intermediate',question:'How do you configure Playwright to retry a failed test up to 2 times?',options:['test.retry(2)','retries: 2 in playwright.config.ts','use: { retries: 2 } in playwright.config.ts','test.configure({retries:2})'],answer:1,explanation:'Setting retries: 2 at the root of playwright.config.ts (or inside a specific project) tells the runner to re-run a failing test up to 2 additional times before marking it as failed, helping reduce flake noise in CI pipelines.'},
{id:4648,topic:'playwright',difficulty:'beginner',question:'Which decorator skips a Playwright test unconditionally?',options:['test.todo()','test.skip()','test.ignore()','test.xfail()'],answer:1,explanation:'test.skip() marks a test as skipped; the test is not executed and appears as skipped in the report. You can pass a condition: test.skip(isMobile, "Not supported on mobile") to skip conditionally based on runtime values.'},
{id:4649,topic:'playwright',difficulty:'beginner',question:'What does `test.fixme()` indicate in Playwright?',options:['The test is expected to pass but is temporarily disabled','The test has a known bug and should be fixed — it runs but is marked as fixme and its failure is not counted as a CI failure','The test fixes a DOM element before assertions','The test retries until it passes'],answer:1,explanation:'test.fixme() marks a test as known-broken. Playwright runs it but treats a failure as expected. If the test unexpectedly passes, the runner warns you so you remember to remove the fixme annotation. It is more informative than a plain skip.'},
{id:4650,topic:'playwright',difficulty:'intermediate',question:'What does the `testInfo` object provide inside a Playwright test?',options:['Browser launch configuration','Metadata about the running test including title, retry count, outputPath, and status','The list of all test files','The current page URL'],answer:1,explanation:'testInfo is injected as the second argument to test() callbacks. It exposes testInfo.title, testInfo.retry (current retry index), testInfo.outputPath() to get a unique file path for attachments, testInfo.status, and more — useful for conditional logic and artifact naming.'},
{id:4651,topic:'playwright',difficulty:'intermediate',question:'How do you get a safe, unique file path for saving a screenshot artifact from within a test?',options:['path.join(__dirname, "screenshot.png")','testInfo.outputPath("screenshot.png")','testInfo.artifactPath("screenshot.png")','page.screenshot({path:"screenshot.png"})'],answer:1,explanation:'testInfo.outputPath(filename) returns a unique path inside the test output directory, namespaced per test and worker, preventing collisions when tests run in parallel. It is the recommended way to write any file artifact during a test.'},
{id:4652,topic:'playwright',difficulty:'intermediate',question:'Which property of testInfo tells you how many times the current test has been retried?',options:['testInfo.retryCount','testInfo.retry','testInfo.attempt','testInfo.failCount'],answer:1,explanation:'testInfo.retry is a zero-based integer: 0 on the first run, 1 on the first retry, etc. You can use it to conditionally take extra diagnostics (screenshots, traces) only on retries to avoid bloating artifact storage on normal runs.'},
{id:4653,topic:'playwright',difficulty:'intermediate',question:'How do you scroll an element into view before interacting with it in Playwright?',options:['locator.scrollIntoView()','locator.scrollIntoViewIfNeeded()','page.scroll(locator)','locator.focus()'],answer:1,explanation:'locator.scrollIntoViewIfNeeded() scrolls the element into the visible viewport only if it is outside the current scroll position. Playwright actions like click() call this automatically, but it can also be called explicitly for custom scroll scenarios.'},
{id:4654,topic:'playwright',difficulty:'intermediate',question:'When using frameLocator, what happens if the iframe src is still loading?',options:['frameLocator throws immediately','frameLocator auto-waits for the iframe to be attached and ready','You must call await frame.waitForLoad() first','You must use page.frames() to find the frame manually'],answer:1,explanation:'frameLocator inherits Playwright auto-waiting. When you call a locator method on a FrameLocator, Playwright waits for the iframe element to be in the DOM and its content to be accessible, so you do not need explicit waits for the iframe load.'},
{id:4655,topic:'playwright',difficulty:'intermediate',question:'Which Playwright method can identify a nested iframe (iframe inside an iframe)?',options:['page.frameLocator("#outer").frameLocator("#inner")','page.frame("outer").frame("inner")','page.nestedFrame("#outer #inner")','page.frames()[0].frames()[0]'],answer:0,explanation:'FrameLocator calls can be chained: page.frameLocator("#outer").frameLocator("#inner") scopes each selector within the previous frame context. This handles arbitrary nesting depth while retaining auto-waiting at each level.'},
{id:4656,topic:'playwright',difficulty:'advanced',question:'You need to interact with a shadow DOM element inside an iframe. Which Playwright approach handles this?',options:['page.evaluate() with shadowRoot.querySelector inside the frame','page.frameLocator("iframe").locator("css=host-element >> .shadow-child")','frameLocator("iframe").locator(".shadow-child") — Playwright locators pierce shadow DOM by default','page.frameLocator("iframe").shadowLocator(".shadow-child")'],answer:2,explanation:'Playwright CSS and text locators automatically pierce open shadow DOM boundaries by default. Combining frameLocator (for the iframe scope) with a standard locator then handles shadow DOM elements seamlessly without needing evaluate() or special selectors.'},
{id:4657,topic:'playwright',difficulty:'advanced',question:'In a multi-tab scenario where tab A triggers tab B to open, and you need to pass data from tab B back to tab A, what is a correct approach?',options:['Playwright cannot share data between page objects','Use page.evaluate() on tab B to set window.__result, then read it from tab A via page.evaluate()','context.sharedStorage can pass data between tabs','Use page.exposeFunction to bridge data'],answer:1,explanation:'Since both pages share the same BrowserContext but separate JavaScript environments, you can store data in the page-level window scope via evaluate() on page B, then navigate page A and read it, or use context-level mechanisms like cookies or localStorage that both pages can access.'},
{id:4658,topic:'playwright',difficulty:'intermediate',question:'What Playwright context option enables recording a video of the entire test?',options:['video: "on"','recordVideo: { dir: "videos/" }','use: { video: "on" } in playwright.config.ts','All of the above are valid forms'],answer:3,explanation:'In playwright.config.ts use block, video:"on" enables recording for every test. recordVideo:{dir} can be passed to browser.newContext() directly. video:"retain-on-failure" is a popular setting that only keeps videos for failing tests to save disk space.'},
{id:4659,topic:'playwright',difficulty:'intermediate',question:'What is the correct way to grant the "clipboard-read" permission and then test clipboard content in Playwright?',options:['context.grantPermissions(["clipboard-read"]); const text = await page.evaluate(() => navigator.clipboard.readText())','page.allowClipboard(); page.evaluate(() => navigator.clipboard.readText())','context.setPermission("clipboard","allow"); page.clipboard.readText()','page.grantPermission("clipboard-read")'],answer:0,explanation:'context.grantPermissions(["clipboard-read"]) unlocks the Clipboard API permission. You then use page.evaluate(() => navigator.clipboard.readText()) to read the clipboard contents. Without granting the permission, the browser denies the API call.'},
{id:4660,topic:'playwright',difficulty:'intermediate',question:'Which configuration option in playwright.config.ts sets a default CSS media type for all pages?',options:['use: { media: "print" }','use: { colorScheme: "print" }','use: { mediaType: "print" }','No built-in config option; use page.emulateMedia() in beforeEach'],answer:0,explanation:'use.media in the config corresponds to the media type passed to page.emulateMedia({media}). Setting it to "print" emulates the CSS @media print rules for all pages, useful for testing print stylesheets globally.'},
{id:4661,topic:'playwright',difficulty:'advanced',question:'How does Playwright handle a page that calls `window.open()` inside a sandboxed iframe?',options:['It throws a security error that cannot be intercepted','The popup event fires on the BrowserContext, not the Page','page.waitForEvent("popup") on the parent page still captures the popup','Sandboxed iframes cannot open windows; Playwright skips it'],answer:2,explanation:'Even when window.open is triggered from within a frame, Playwright routes the resulting popup event through the top-level Page\'s event emitter. Using page.waitForEvent("popup") on the parent page correctly captures it.'},
{id:4662,topic:'playwright',difficulty:'intermediate',question:'What does `locator.dragTo(target, { sourcePosition, targetPosition })` allow you to specify?',options:['CSS animations to trigger during drag','Exact pixel offsets within the source and target elements for the drag start and drop end points','The drag speed in pixels per second','Whether to hold Shift during the drag'],answer:1,explanation:'sourcePosition and targetPosition are {x, y} offsets relative to the top-left corner of each element. They let you simulate dropping at a specific location within a target element, important for canvas-based or grid-based drag-and-drop implementations.'},
{id:4663,topic:'playwright',difficulty:'intermediate',question:'Which approach correctly emulates a device with touch support in Playwright?',options:['page.setHasTouch(true)','browser.newContext({hasTouch:true, isMobile:true})','context.enableTouch()','page.emulate({touch:true})'],answer:1,explanation:'Passing hasTouch:true to browser.newContext() enables touch events. isMobile:true additionally adjusts the meta viewport. When using playwright.devices, these flags are included in the spread descriptor automatically for defined mobile devices.'},
{id:4664,topic:'playwright',difficulty:'intermediate',question:'What is forced-colors emulation used for in Playwright?',options:['Forcing all CSS colors to specific brand colors','Emulating the Windows High Contrast / forced-colors accessibility mode to test color-adaptive UI','Forcing dark mode on all elements','Disabling CSS transitions involving color changes'],answer:1,explanation:'forced-colors:"active" emulates the CSS prefers-forced-colors media feature, which is triggered in Windows High Contrast Mode. Testing with this emulation helps ensure UI elements remain usable when colors are overridden by the OS for accessibility.'},
{id:4665,topic:'playwright',difficulty:'advanced',question:'You set context.setOffline(true) midway through a test. What happens to in-flight requests that were already sent?',options:['They are immediately aborted with a network error','They complete normally because they were already in flight before offline was set','The browser queues them and retries when reconnected','context.setOffline is not supported mid-test'],answer:1,explanation:'Requests that were already sent before setOffline(true) complete normally. Only new requests initiated after the offline flag is set receive "net::ERR_INTERNET_DISCONNECTED" or equivalent network errors. This mirrors real browser offline behavior.'},
{id:4666,topic:'playwright',difficulty:'intermediate',question:'In playwright.config.ts, how do you reference a saved storageState file for all tests?',options:['use: { storageState: "auth.json" }','globalSetup: "auth.json"','setup: { auth: "auth.json" }','storageState: { file: "auth.json" }'],answer:0,explanation:'Placing storageState: "auth.json" inside the use block applies the saved cookies and Web Storage to every BrowserContext created by the test runner. This is the most common pattern for sharing a logged-in session across all tests.'},
{id:4667,topic:'playwright',difficulty:'advanced',question:'How should you handle multiple user roles (admin and regular user) with storageState?',options:['Create two separate browser contexts manually in every test','Define two projects in playwright.config.ts each with a different storageState, or use a fixture that selects the right state based on a test tag','Use a single storageState that combines both roles','Store role data in environment variables'],answer:1,explanation:'The multi-project pattern is idiomatic: define projects like {name:"admin", use:{storageState:"admin-auth.json"}} and {name:"user", use:{storageState:"user-auth.json"}}. Tests can be annotated with @project or the projects list controls which suite uses which auth state.'},
{id:4668,topic:'playwright',difficulty:'intermediate',question:'What is the purpose of the `webServer` option in playwright.config.ts?',options:['It sets the browser server address for remote execution','It automatically starts a local dev server before tests run and stops it afterward','It specifies the URL of a running server to health-check before tests start','Both B and C are correct'],answer:3,explanation:'webServer: {command, url, reuseExistingServer} starts a development server process (e.g., npm start) before the test suite and waits for the given URL to become available. reuseExistingServer:true skips the start if it is already running, useful for local dev.'},
{id:4669,topic:'playwright',difficulty:'beginner',question:'Which CLI command opens the HTML test report generated by the built-in HTML reporter?',options:['npx playwright report','npx playwright show-report','npx playwright open-report','npx playwright html-report'],answer:1,explanation:'npx playwright show-report opens the latest HTML report in a local web server at localhost:9323 by default. The HTML reporter generates an index.html in the playwright-report/ directory after each test run.'},
{id:4670,topic:'playwright',difficulty:'intermediate',question:'How do you configure the HTML reporter in playwright.config.ts to open the report automatically after a failed run?',options:['reporter: [["html", { open: "on-failure" }]]','reporter: "html-auto"','reporter: [["html", { autoOpen: true }]]','reporter: { html: { openOnFail: true } }'],answer:0,explanation:'The HTML reporter accepts an options object as the second element in its tuple. Setting open:"on-failure" (or "always"/"never") controls when the browser automatically opens the report. The default behavior is "on-failure".'},
{id:4671,topic:'playwright',difficulty:'intermediate',question:'What does `page.waitForLoadState()` default to when called with no arguments?',options:['"networkidle"','"load"','"domcontentloaded"','"commit"'],answer:1,explanation:'Without arguments, page.waitForLoadState() waits for the "load" state, which corresponds to the window load event firing after all initial subresources (images, stylesheets, scripts) have been downloaded.'},
{id:4672,topic:'playwright',difficulty:'advanced',question:'You navigate to a page that immediately redirects multiple times. Which approach reliably waits for the final URL?',options:['page.waitForNavigation({url: finalUrl})','page.waitForURL(finalUrl)','await page.goto(url); — goto resolves after all redirects automatically','Both B and C are reliable'],answer:3,explanation:'page.goto() follows redirects and resolves after the last navigation completes (using the "load" wait state by default). page.waitForURL(finalUrl) can also be used after a triggering action to assert the final URL, retrying until it matches.'},
{id:4673,topic:'playwright',difficulty:'intermediate',question:'What value does `testInfo.outputPath("trace.zip")` return?',options:['A URL to upload the trace to Trace Viewer','An absolute file path unique to the current test inside the test output directory','The relative path "./test-results/trace.zip"','The path defined in the outputDir config'],answer:1,explanation:'testInfo.outputPath() joins the test-specific output directory (based on outputDir config + test title hash) with the given filename. Using it guarantees no filename collisions when tests run in parallel across multiple workers.'},
{id:4674,topic:'playwright',difficulty:'intermediate',question:'How do you conditionally skip a test in Playwright based on the browser name?',options:['test.skip(browserName === "firefox", "Not supported in Firefox")','if (browserName==="firefox") test.skip()','test.skipBrowser("firefox")','test.use({browser:"chromium"}) implicitly skips on others'],answer:0,explanation:'test.skip(condition, reason) accepts a boolean condition as the first argument. Using the browserName fixture (available via the test function signature) allows conditional skipping per browser without modifying test structure.'},
{id:4675,topic:'playwright',difficulty:'advanced',question:'What is a risk of relying heavily on `waitForLoadState("networkidle")` in SPA tests?',options:['It is not supported in Firefox','It can cause tests to time out in apps that maintain persistent WebSocket or polling connections','It ignores CSS loading','It only works in headed mode'],answer:1,explanation:'SPAs often maintain background polling, WebSocket connections, or analytics beacons, so networkidle may never be reached (or may take many seconds), causing slow or flaky tests. Prefer waiting for specific UI elements or API responses that indicate the page is ready.'},
{id:4676,topic:'playwright',difficulty:'intermediate',question:'Which Playwright assertion checks that a specific network response was received?',options:['await expect(page).toHaveResponse(url)','await page.waitForResponse(urlOrPredicate) combined with response assertions','page.assertNetworkCall(url, 200)','locator.waitForNetwork(url)'],answer:1,explanation:'page.waitForResponse(urlOrPredicate) returns a Response object once a matching request completes. You can then assert response.status(), response.json(), etc. There is no built-in toHaveResponse assertion — you compose waitForResponse with standard expect calls.'},
{id:4677,topic:'playwright',difficulty:'intermediate',question:'In a test, you need to verify a form input has a specific value. Which is the correct web-first assertion?',options:['expect(await locator.inputValue()).toBe("expected")','await expect(locator).toHaveValue("expected")','locator.assertValue("expected")','expect(locator.value).toBe("expected")'],answer:1,explanation:'await expect(locator).toHaveValue("expected") retries the check until the input\'s value matches, handling delayed form population (e.g., from async autofill or computed defaults) correctly. The synchronous inputValue() + toBe approach does not retry.'},
{id:4678,topic:'playwright',difficulty:'beginner',question:'Which fixture provided by @playwright/test gives the current browser name inside a test?',options:['browser.name()','context.browserName','browserName (built-in fixture)','playwright.browserType'],answer:2,explanation:'browserName is a built-in fixture that resolves to "chromium", "firefox", or "webkit" depending on which project is running the test. You can destructure it in the test callback: test("name", ({browserName}) => ...).'},
{id:4679,topic:'playwright',difficulty:'intermediate',question:'How does `test.use({ locale: "de-DE" })` affect a test?',options:['It translates test assertions to German','It sets the Accept-Language header and navigator.language for all pages in the test file scope','It changes the test runner output language','It skips the test on non-German locales'],answer:1,explanation:'test.use() overrides fixture values for the current describe block or file scope. locale:"de-DE" sets the HTTP Accept-Language header and the browser\'s locale APIs, enabling testing of locale-specific formatting, translations, and date/number rendering.'},
{id:4680,topic:'playwright',difficulty:'intermediate',question:'Which Playwright concept allows sharing the same logged-in page across multiple tests in a describe block for speed?',options:['Using test.use({storageState}) with context-scoped fixtures','Storing the page in a beforeAll and using a scope:"worker" fixture','Using test.share(page)','global page variable in the describe block'],answer:1,explanation:'A custom fixture with scope:"worker" (or scope:"file") creates the resource once per worker/file rather than per test. Combining this with storageState in a beforeAll means a single login session is shared, skipping repeated logins while keeping test isolation configurable.'},
{id:4681,topic:'playwright',difficulty:'advanced',question:'What is the difference between `test.describe.serial()` and the default `test.describe()` in Playwright?',options:['serial runs tests on a single thread; default uses multiple threads','serial runs tests inside the describe block sequentially in the same worker, sharing state; default allows parallel execution across workers','serial retries each test until pass; default marks failures immediately','serial is for API tests; default is for browser tests'],answer:1,explanation:'test.describe.serial() forces tests in the group to run one after another in the same worker, in order. This is needed when tests are intentionally stateful (e.g., wizard flows). The default describe allows tests to run in any order across workers.'},
{id:4682,topic:'playwright',difficulty:'intermediate',question:'What does `test.only()` do in a Playwright test file?',options:['Marks the test as the only one that can pass','Runs only that test (and other .only tests) while skipping all others in the suite','Forces the test to run on all browsers','Marks it as a priority-1 test in reports'],answer:1,explanation:'test.only() limits execution to tagged tests during a run. It is useful during development for focusing on a single failing test without commenting out others. The --grep flag is the CI-safe alternative since committed .only calls skip large parts of the suite.'},
{id:4683,topic:'playwright',difficulty:'advanced',question:'How do you pass data from a Playwright globalSetup to individual tests?',options:['Return data from globalSetup and access it via process.env or a shared file','Playwright has a built-in globalData fixture for this','Use test.use({globalData: data}) in playwright.config.ts','Store data in a globalSetup.ts singleton module and import it in tests'],answer:0,explanation:'globalSetup runs in a separate Node.js process, so the only reliable communication channels are environment variables (process.env.KEY=value) or writing to a JSON file that tests read via a custom fixture. Direct module exports do not cross the worker process boundary.'},
{id:4684,topic:'playwright',difficulty:'intermediate',question:'Which Playwright feature lets you assert that a page element does NOT exist?',options:['await expect(locator).not.toBeVisible()','await expect(locator).toNotExist()','await expect(locator).hidden()','page.assertNotExists(locator)'],answer:0,explanation:'Chaining .not before any assertion negates it. await expect(locator).not.toBeVisible() retries until the element is either absent from the DOM or hidden. toBeHidden() is the positive form; both handle the case where an element may not be in the DOM at all.'},
{id:4685,topic:'playwright',difficulty:'intermediate',question:'What does `await expect(locator).toHaveCount(3)` assert?',options:['The locator matches exactly 3 elements in the DOM','The text of the locator contains the number 3','The element has been clicked 3 times','The element has 3 CSS classes'],answer:0,explanation:'toHaveCount(n) retries until the locator resolves to exactly n matching elements. It is useful for asserting the number of list items, table rows, or any repeated component pattern after dynamic rendering.'},
{id:4686,topic:'playwright',difficulty:'intermediate',question:'Which Playwright method returns a list of all inner text values for a multi-match locator?',options:['locator.allTextContents()','locator.texts()','locator.getAll().map(l => l.textContent())','locator.innerTexts()'],answer:0,explanation:'locator.allTextContents() returns a Promise<string[]> with the innerText of every element matching the locator. It is useful for asserting or inspecting lists of items without manually iterating with for loops.'},
{id:4687,topic:'playwright',difficulty:'intermediate',question:'How can you iterate over each element in a locator that matches multiple elements?',options:['for(const el of await locator.elementHandles())','await locator.each(async el => {})','for(let i=0;i<await locator.count();i++) { await locator.nth(i).action() }','locator.forEach(async el => {})'],answer:2,explanation:'The idiomatic Playwright pattern for iterating multiple locator matches is getting the count and using locator.nth(i) to address each one. This keeps everything in the locator/auto-wait system. elementHandles() is lower-level and bypasses auto-waiting.'},
{id:4688,topic:'playwright',difficulty:'advanced',question:'What is the behavior when you call `locator.fill("")` on an input that has a required validator?',options:['Playwright throws a validation error','The input is cleared and the browser shows native validation UI, but the test continues','Playwright automatically submits the form to trigger validation','fill("") sets the value to a space character'],answer:1,explanation:'fill("") clears the input value. The browser may show constraint validation UI (e.g., "This field is required") on form submission or focus-out events, but Playwright itself does not throw — it simply sets the value. You can then assert the validation message separately.'},
{id:4689,topic:'playwright',difficulty:'intermediate',question:'Which config option controls the directory where test result artifacts (videos, screenshots, traces) are saved?',options:['artifactsDir','outputDir','resultsDir','testOutputDir'],answer:1,explanation:'outputDir in playwright.config.ts sets the root directory for all test output files. Defaults to "test-results". testInfo.outputPath() resolves relative to a per-test subdirectory within outputDir.'},
{id:4690,topic:'playwright',difficulty:'intermediate',question:'How do you run a Playwright test against only the Firefox project defined in playwright.config.ts?',options:['npx playwright test --browser=firefox','npx playwright test --project=firefox','npx playwright test -b firefox','SET BROWSER=firefox npx playwright test'],answer:1,explanation:'--project=<name> filters the run to a named project from playwright.config.ts. Projects typically map to browser configurations (chromium, firefox, webkit) or device emulation profiles, and you can combine multiple: --project=chromium --project=firefox.'},
{id:4691,topic:'playwright',difficulty:'intermediate',question:'What is the effect of `use: { actionTimeout: 10000 }` in playwright.config.ts?',options:['Sets a 10-second timeout for the entire test suite','Sets the default timeout for each individual action (click, fill, etc.) to 10 seconds','Sets the assertion retry timeout to 10 seconds','Sets the navigation timeout to 10 seconds'],answer:1,explanation:'actionTimeout sets the default timeout applied to each individual Playwright action (locator.click, locator.fill, etc.). It is separate from the test timeout (which covers the whole test) and the assertion timeout configured under expect.timeout.'},
{id:4692,topic:'playwright',difficulty:'intermediate',question:'How do you set a navigation-specific timeout differently from the action timeout?',options:['use: { navigationTimeout: 30000 } in playwright.config.ts','use: { gotoTimeout: 30000 }','page.setTimeout(30000) before every goto','navigation timeout is always equal to action timeout'],answer:0,explanation:'navigationTimeout in the use block (or per-page via page.setDefaultNavigationTimeout()) sets the timeout for goto(), waitForURL(), and other navigation operations. It defaults to 30 seconds if not overridden and is distinct from actionTimeout.'},
{id:4693,topic:'playwright',difficulty:'advanced',question:'Playwright auto-waiting checks several conditions before acting. Which of the following is NOT one of the default actionability checks?',options:['Visible','Enabled','Stable (not animating)','Has focus'],answer:3,explanation:'Default actionability checks for click() include: visible, enabled, stable (no ongoing CSS animation), and attached to the DOM. "Has focus" is not a default check — Playwright does not require an element to be focused before acting on it.'},
{id:4694,topic:'playwright',difficulty:'advanced',question:'What does `locator.click({ force: true })` bypass?',options:['Network requests triggered by the click','Actionability checks (visible, enabled, stable) — it dispatches the click event regardless','The shadow DOM boundary','The frame scope of a FrameLocator'],answer:1,explanation:'force:true skips all actionability checks and dispatches the event directly. It should be used sparingly — only when the app\'s rendering prevents standard actionability from passing and you have verified the element is logically clickable (e.g., covered by an overlay you have already dismissed).'},
{id:4695,topic:'playwright',difficulty:'intermediate',question:'Which Playwright method lets you evaluate JavaScript that returns a non-serializable object (like a DOM element)?',options:['page.evaluate()','page.evaluateHandle()','page.exposeFunction()','page.addScriptTag()'],answer:1,explanation:'page.evaluateHandle() executes JavaScript in the page and returns a JSHandle (or ElementHandle) wrapping the result. Unlike evaluate(), which must return a JSON-serializable value, evaluateHandle can hold references to DOM nodes, complex objects, or functions.'},
{id:4696,topic:'playwright',difficulty:'intermediate',question:'How does Playwright\'s `page.exposeFunction()` work?',options:['It exposes a Node.js function as a callable global inside the browser page\'s JavaScript environment','It exposes a browser function to the Node.js test script','It polyfills missing browser APIs','It adds the function to the page\'s prototype chain'],answer:0,explanation:'page.exposeFunction(name, callback) registers a Node.js function under a global name in the browser page. When page JS calls window[name](...args), Playwright routes the call to the Node.js callback and returns the result, enabling bi-directional communication.'},
{id:4697,topic:'playwright',difficulty:'advanced',question:'You want to intercept all requests to "/api/users" and return an empty array. Which route.fulfill call is correct?',options:['route.fulfill({body:"[]",contentType:"application/json"})','route.fulfill({json:[]})','route.fulfill({status:200,body:JSON.stringify([]),headers:{"content-type":"application/json"}})','Both A and C are correct; B uses the shorthand json option available in recent Playwright versions'],answer:3,explanation:'route.fulfill({body:"[]",contentType:"application/json"}) and the explicit headers form both work. Playwright v1.29+ also added the json shorthand: route.fulfill({json:[]}) which automatically sets content-type and serializes the value, making it the most concise approach.'},
{id:4698,topic:'playwright',difficulty:'intermediate',question:'Which Playwright method allows you to modify a real network request before it is sent (e.g., adding an auth header)?',options:['route.intercept()','route.continue({headers:{...}})','route.modify()','route.patch()'],answer:1,explanation:'route.continue({headers: {...mergedHeaders}}) forwards the request with modified properties. You can override headers, postData, url, or method. Unlike route.fulfill(), the real server still receives and processes the request.'},
{id:4699,topic:'playwright',difficulty:'advanced',question:'What is the difference between `page.route()` and `context.route()` in Playwright?',options:['page.route intercepts all pages; context.route intercepts only the main page','context.route applies to all pages within the context; page.route applies only to that specific page','They are identical — route is a shared alias','context.route only works for background service worker requests'],answer:1,explanation:'context.route() registers a handler at the BrowserContext level, intercepting matching requests from any page (including popups and iframes) within that context. page.route() is scoped only to the specific Page instance. Use context.route() for broad API mocking shared across pages.'},
{id:4700,topic:'playwright',difficulty:'advanced',question:'Which approach correctly handles a scenario where you need to wait for a specific API response body during a test?',options:['const res = await page.waitForResponse(r => r.url().includes("/api/data") && r.status() === 200); const body = await res.json();','page.on("response", r => r.json()); await page.waitForTimeout(1000)','await expect(page).toHaveResponse("/api/data", {status:200})','page.route("/api/data", async route => { const res = await route.fetch(); expect(await res.json()).toBeTruthy(); route.continue() })'],answer:0,explanation:'page.waitForResponse(predicate) returns a Response matching the predicate (URL + status check). Calling await res.json() then reads the body. The predicate fires when the response headers arrive; the body is buffered and available via res.json(). This is the canonical pattern for API response assertions.'},
]);
